select database_role, open_mode, case when database_role = 'PRIMARY' then null else transport_lag_sec end as transport_lag_sec, case when database_role = 'PRIMARY' then null else apply_lag_sec end as apply_lag_sec, case when database_role = 'PRIMARY' then null else primary_contact_age_sec end as primary_contact_age_sec, case when database_role = 'PRIMARY' then null else mrp_processes end as mrp_processes, case when database_role = 'PRIMARY' then 'PRIMARY' when transport_lag_sec is null or apply_lag_sec is null or mrp_processes = 0 then 'UNKNOWN' else 'OK' end as lag_status from (select (select database_role from v$database) as database_role, (select open_mode from v$database) as open_mode, (select round(extract(day from to_dsinterval(value)) * 86400 + extract(hour from to_dsinterval(value)) * 3600 + extract(minute from to_dsinterval(value)) * 60 + extract(second from to_dsinterval(value))) from v$dataguard_stats where name = 'transport lag') as transport_lag_sec, (select round(extract(day from to_dsinterval(value)) * 86400 + extract(hour from to_dsinterval(value)) * 3600 + extract(minute from to_dsinterval(value)) * 60 + extract(second from to_dsinterval(value))) from v$dataguard_stats where name = 'apply lag') as apply_lag_sec, (select round((sysdate - to_date(datum_time, 'MM/DD/YYYY HH24:MI:SS')) * 86400) from v$dataguard_stats where name = 'transport lag') as primary_contact_age_sec, (select count(*) from gv$dataguard_process where name like 'MRP%') as mrp_processes from dual)
